<script lang="ts">
	import { onMount } from "svelte";
	import { advanceSearch, createSearch, recommendedAction } from "@/utils/mcts";
	let english = $state(false);
	let budget = $state(50);
	let exploration = $state(1.4);
	let seed = $state(7);
	let state = $state(createSearch());
	let running = $state(false);
	let reveal = $state(false);
	let copyStatus = $state<"" | "ok" | "error">("");
	let timer: ReturnType<typeof setInterval> | undefined;
	const recommendation = $derived(recommendedAction(state));
	const actions = $derived(state.nodes[0].children.map((id) => state.nodes[id]));
	const finished = $derived(state.iterations >= budget);
	const phases = $derived(english ? ["Ready", "Selection", "Expansion", "Simulation", "Backup"] : ["准备开始", "选择", "扩展", "模拟", "回传"]);
	const explanation = $derived(state.phase === 0 ? (english ? "Step through one search to see how feedback changes the tree." : "点击下一步，看一次搜索的反馈怎样改变这棵树。") : state.phase === 1 ? (english ? "Follow the highest UCT score until an unexpanded action or terminal state is reached." : "沿 UCT 得分最高的分支前进，遇到尚未扩展的动作或终点时停下。") : state.phase === 2 ? (state.expandedId === null ? (english ? "This is already a terminal state; no new node is needed." : "已到达终点，本轮无需增加新节点。") : (english ? "Add one untried child to the search tree." : "选一个尚未尝试的动作，加入一个新节点。")) : state.phase === 3 ? (english ? "Roll out uniformly at random to a leaf and read its fixed reward." : "从当前节点均匀随机地走到叶子，读取终点的固定奖励。") : (english ? "Add one visit and the reward to each node on the expanded search path. Dashed rollout nodes are not updated." : "搜索路径上的节点各增加一次访问和本轮奖励；虚线模拟经过的未扩展节点不更新。"));
	function pause() { if (timer) clearInterval(timer); timer = undefined; running = false; }
	function step() { if (finished) { pause(); return; } state = advanceSearch(state, exploration); if (state.iterations >= budget) pause(); }
	function play() { if (running) { pause(); return; } running = true; timer = setInterval(step, 420); }
	function reset() { pause(); state = createSearch(seed); copyStatus = ""; }
	function finish() { pause(); let next = state; while (next.iterations < budget) next = advanceSearch(next, exploration); state = next; }
	async function share() { const url = new URL(location.href); url.search = new URLSearchParams({ budget: String(budget), c: String(exploration), seed: String(seed) }).toString(); try { await navigator.clipboard.writeText(url.href); copyStatus = "ok"; } catch { copyStatus = "error"; } history.replaceState({}, "", url); }
	onMount(() => {
		const sync = () => { english = document.documentElement.lang.startsWith("en"); };
		sync(); document.addEventListener("site-locale-change", sync);
		const params = new URL(location.href).searchParams;
		const queryBudget = Number(params.get("budget")); const queryC = params.has("c") ? Number(params.get("c")) : 1.4; const querySeed = Number(params.get("seed"));
		if ([10, 50, 200].includes(queryBudget)) budget = queryBudget;
		if (Number.isFinite(queryC) && queryC >= 0 && queryC <= 3) exploration = Math.round(queryC * 10) / 10;
		if ([7, 19, 42].includes(querySeed)) seed = querySeed;
		reset();
		const hide = () => { if (document.hidden) pause(); }; document.addEventListener("visibilitychange", hide);
		return () => { pause(); document.removeEventListener("site-locale-change", sync); document.removeEventListener("visibilitychange", hide); };
	});
</script>

<section class="mcts" aria-label={english ? "Interactive Monte Carlo tree search" : "蒙特卡洛树搜索互动实验"}>
	<div class="controls">
		<label for="search-budget">{english ? "Search budget" : "搜索预算"}<select id="search-budget" value={budget} onchange={(event) => { budget = Number(event.currentTarget.value); reset(); }}><option value={10}>10</option><option value={50}>50</option><option value={200}>200</option></select></label>
		<label for="exploration">{english ? "Exploration weight c" : "探索权重 c"}<span class="range"><input id="exploration" type="range" min="0" max="3" step="0.1" value={exploration} oninput={(event) => { exploration = Number(event.currentTarget.value); reset(); }} /><output for="exploration">{exploration.toFixed(1)}</output></span></label>
		<label for="search-seed">{english ? "Random seed" : "随机种子"}<select id="search-seed" value={seed} onchange={(event) => { seed = Number(event.currentTarget.value); reset(); }}><option value={7}>7</option><option value={19}>19</option><option value={42}>42</option></select></label>
	</div>
	<div class="actions"><button onclick={step} disabled={running || finished}>{english ? "Next phase" : "下一步"} →</button><button onclick={play} disabled={finished}>{running ? (english ? "Pause" : "暂停") : (english ? "Play slowly" : "慢速演示")}</button><button onclick={finish} disabled={finished}>{english ? "Finish budget" : "跑完预算"}</button><button class="quiet" onclick={reset}>{english ? "Reset" : "重置"}</button></div>
	<div class="phase-strip" aria-label={english ? "Search phases" : "搜索阶段"}>{#each phases.slice(1) as phase, index}<span class:active={state.phase === index + 1} aria-current={state.phase === index + 1 ? "step" : undefined}>0{index + 1} / {phase}</span>{/each}</div>
	<div class="phase-status" role="status" aria-live={running ? "off" : "polite"}><strong>{finished ? (english ? "Budget complete" : "预算已用完") : phases[state.phase]} <span>{state.iterations} / {budget}</span></strong><p>{explanation}</p></div>
	<p class="tree-scroll-hint">{english ? "Scroll the tree sideways to see all branches ↔" : "横向滑动搜索树，查看所有分支 ↔"}</p>
	<div class="tree-wrap" tabindex="0" role="region" aria-label={english ? "Search tree, horizontally scrollable" : "搜索树，可横向滚动"}><svg viewBox="0 0 960 425" role="img" aria-labelledby="mcts-tree-title mcts-tree-description"><title id="mcts-tree-title">{english ? "Search tree" : "搜索树"}</title><desc id="mcts-tree-description">{english ? `Completed ${state.iterations} iterations. Current recommendation ${recommendation?.label ?? "none"}. Visit counts and mean rewards are also listed below.` : `已完成 ${state.iterations} 轮，当前建议 ${recommendation?.label ?? "暂无"}。根动作的访问次数与平均奖励也列在下方。`}</desc>
		{#each state.nodes.filter((node) => node.parent !== null) as node}{@const parent = state.nodes[node.parent!]}
			<line x1={parent.x} y1={parent.y + 18} x2={node.x} y2={node.y - 17} class:searched={state.path.includes(node.id)} class:rollout={state.rollout.includes(node.id) && !state.path.includes(node.id)} class:known={node.expanded} />
		{/each}
		{#each state.nodes as node}<g class:unexpanded={!node.expanded} class:selected={state.path.includes(node.id)}><circle cx={node.x} cy={node.y} r={node.parent === null ? 23 : 18} /><text x={node.x} y={node.y + 4} class="node-name">{node.label}</text><text x={node.x} y={node.y + 36}>N {node.visits}</text>{#if node.reward !== null && (reveal || state.rollout.includes(node.id))}<text x={node.x} y={node.y + 54} class="reward">r {node.reward.toFixed(2)}</text>{/if}</g>{/each}
	</svg></div>
	<div class="tree-key"><span><i class="solid"></i>{english ? "Search path" : "搜索路径"}</span><span><i class="dashed"></i>{english ? "Random rollout" : "随机模拟"}</span><label><input type="checkbox" bind:checked={reveal} />{english ? "Reveal all leaf rewards" : "显示全部终点奖励"}</label></div>
	<div class="results"><div class="recommendation"><small>{english ? "MOST VISITED ROOT ACTION" : "按访问次数选择根动作"}</small><strong>{recommendation?.label ?? "—"}</strong><p>{english ? "Visits first; mean reward breaks ties. This is the current search result, not a guarantee of the optimum." : "优先选访问最多的动作，同次数时比较平均奖励。这是当前搜索的建议，有限预算下不保证最优。"}</p></div><div class="stats-wrap"><table><caption>{english ? "Root action statistics" : "根动作统计"}</caption><thead><tr><th>{english ? "Action" : "动作"}</th><th>N</th><th>{english ? "Mean Q" : "平均 Q"}</th><th>{english ? "Explore bonus" : "探索项"}</th></tr></thead><tbody>{#each actions as node}<tr class:best={recommendation?.id === node.id}><th>{node.label}</th><td>{node.visits}</td><td>{node.visits ? (node.total / node.visits).toFixed(3) : "—"}</td><td>{node.visits ? (exploration * Math.sqrt(Math.log(Math.max(1, state.nodes[0].visits)) / node.visits)).toFixed(3) : "∞"}</td></tr>{/each}</tbody></table></div></div>
	<div class="share"><button class="quiet" onclick={share}>{english ? "Copy experiment settings" : "复制实验配置链接"} ↗</button><span role="status">{copyStatus === "ok" ? (english ? "Copied. The link restarts with these settings." : "已复制，打开链接可从这组参数重新开始。") : copyStatus === "error" ? (english ? "Copy the updated address from your browser." : "请从浏览器地址栏复制已更新的链接。") : ""}</span></div>
	<details class="assumptions"><summary>{english ? "What this experiment does" : "实验的规则与边界"}</summary><p>{english ? "This is a single-agent tree with three root actions and fixed terminal rewards in [0, 1]. Every decision aims to maximize the same reward; no opponent or network training is involved. Grey nodes show the possible state space, while the search tree expands one node per iteration." : "这是一个单智能体决策树：根节点有三个动作，终点奖励固定在 [0, 1]。每一步都最大化同一个奖励，不涉及对手或网络训练。灰色节点展示可能的状态空间，搜索树每轮最多扩展一个节点。"}</p><p class="formula">UCT = Q + c √(ln N<sub>parent</sub> / N<sub>child</sub>)</p><p>{english ? "Q is the mean observed reward. Untried actions are expanded first; equal scores are broken with seeded randomness. Rollouts choose uniformly. Rewards are backed up only along the expanded search path. Changing a parameter resets the search; identical settings reproduce the same sequence." : "Q 是已观察奖励的平均值。先扩展未尝试的动作；相同分数用带种子的随机数打破平局。模拟阶段均匀随机选择，奖励仅沿已扩展的搜索路径回传。修改参数会重置搜索，相同配置产生相同序列。"}</p><p>{english ? "Try c = 0 and c = 1.4 with the same budget and seed. Which branches get overlooked? Then increase the budget. More search can change a decision without changing any learned model." : "试着在相同预算和种子下比较 c = 0 与 c = 1.4：哪些分支会被忽略？再增加预算。即使没有更新模型参数，更多搜索也可能改变决策。"}</p><a href="https://doi.org/10.1109/TCIAIG.2012.2186810">Browne et al. (2012), §3 — MCTS / UCT ↗</a></details>
</section>
<style>
	.mcts{border:1px solid var(--brand-line);border-radius:18px;background:var(--brand-surface);padding:26px;color:var(--brand-ink)}.controls{display:grid;grid-template-columns:1fr 1.5fr 1fr;gap:24px}.controls>label{display:grid;gap:12px;font-size:12px}.range{display:flex;gap:14px;align-items:center}input[type=range]{width:100%;accent-color:var(--brand-accent)}input[type=checkbox]{accent-color:var(--brand-accent)}select{padding:9px;border:1px solid var(--brand-line);border-radius:8px;background:var(--brand-paper);color:inherit}.range output{font:12px monospace}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}button{font-size:12px;border:1px solid var(--brand-line);border-radius:24px;padding:11px 16px;background:var(--brand-peach);color:var(--brand-ink);cursor:pointer}button:disabled{opacity:.45;cursor:default}button.quiet{background:transparent}.phase-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;border-top:1px solid var(--brand-line);padding-top:20px}.phase-strip span{padding:12px 7px;font:11px/1.6 monospace;border-radius:6px;color:var(--brand-muted)}.phase-strip .active{background:var(--brand-accent);color:var(--brand-paper)}.phase-status{min-height:108px;padding-top:22px}.phase-status strong{display:flex;justify-content:space-between;gap:10px;font-size:14px;font-weight:500}.phase-status strong span{font:12px monospace;color:var(--brand-accent)}.phase-status p,.recommendation p,.assumptions p{font-size:12px;line-height:1.9;color:var(--brand-body)}.tree-wrap{overflow-x:auto;border:1px solid var(--brand-line);border-radius:12px;background:var(--brand-paper)}svg{display:block;width:100%;min-width:640px;height:auto}line{stroke:var(--brand-line);stroke-width:1.5}line.known{stroke:var(--brand-muted)}line.searched{stroke:var(--brand-accent);stroke-width:3}line.rollout{stroke:var(--brand-clay);stroke-dasharray:5 4;stroke-width:2}circle{fill:var(--brand-surface);stroke:var(--brand-accent);stroke-width:1.5}.unexpanded circle{stroke:var(--brand-line);fill:var(--brand-paper)}.selected circle{fill:var(--brand-accent)}text{fill:var(--brand-muted);text-anchor:middle;font:11px monospace}.node-name{fill:var(--brand-ink);font-size:10px}.selected .node-name{fill:var(--brand-paper)}.reward{fill:var(--brand-clay)}.tree-key{display:flex;align-items:center;flex-wrap:wrap;gap:12px 20px;padding:15px 0;font-size:10px;color:var(--brand-body)}.tree-key>span,.tree-key label{display:flex;align-items:center;gap:7px}.tree-key i{width:18px;border-top:2px solid var(--brand-accent)}.tree-key .dashed{border-top:2px dashed var(--brand-clay)}.results{display:grid;grid-template-columns:1fr 1.6fr;gap:25px;margin-top:12px}.recommendation{padding:22px;background:var(--brand-paper);border-radius:12px}.recommendation small{font-size:9px;color:var(--brand-muted)}.recommendation strong{display:block;font:54px Georgia,serif;color:var(--brand-accent);margin-top:10px}.stats-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font:12px/1.8 monospace}caption{text-align:left;font-size:11px;margin:15px 0}th,td{text-align:left;padding:12px 8px;border-bottom:1px solid var(--brand-line);white-space:nowrap}th{font-weight:500}.best{background:var(--brand-paper);color:var(--brand-accent)}.share{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-top:24px}.share span{font-size:11px;color:var(--brand-body)}.assumptions{margin-top:24px;border-top:1px solid var(--brand-line);padding-top:20px}.assumptions summary{font-size:13px;cursor:pointer;color:var(--brand-accent)}.assumptions a{font-size:11px;color:var(--brand-accent)}.formula{font-family:monospace}@media(max-width:650px){.mcts{padding:18px}.controls{grid-template-columns:1fr 1fr;gap:18px}.controls>label:nth-child(2){grid-column:1/-1;grid-row:2}.phase-strip span{font-size:9px;padding:10px 4px}.phase-status{min-height:140px}.results{grid-template-columns:1fr;gap:10px}.recommendation{display:grid;grid-template-columns:1fr 50px;align-items:center}.recommendation strong{grid-column:2;grid-row:1/3;font-size:44px}.recommendation p{margin-bottom:0}.actions{gap:8px}button{font-size:11px;padding:10px 13px}}
	.tree-scroll-hint{display:none;font-size:10px;color:var(--brand-muted);margin:0 0 10px}@media(max-width:760px){.tree-scroll-hint{display:block}}
</style>
